package org.codex.nfsugpreview;
import java.nio.*;import java.nio.file.*;import java.util.*;
public final class SourceBackgroundBindingTest {
 static byte[] bytes(ByteBuffer b){byte[] a=new byte[b.remaining()];b.get(a);return a;}
 static byte[] section(byte[] raw,int part){ByteBuffer b=ByteBuffer.wrap(raw).order(ByteOrder.LITTLE_ENDIAN);int at=(int)b.getLong(64+part*16),size=(int)b.getLong(72+part*16);return Arrays.copyOfRange(raw,at,at+size);}
 public static void main(String[] args)throws Exception{Path dir=Paths.get(args[0]),reference=Paths.get(args[1]);NativeSourceSceneBinding binding=new NativeSourceSceneBinding();int snapshots=0,owners=0,rgba=0,rejected=0;try(DirectoryStream<Path> files=Files.newDirectoryStream(dir,"race-background-*.nrb")){for(Path file:files){byte[] raw=Files.readAllBytes(file);NativeBackgroundScene legacy=new NativeBackgroundScene(raw);NativeSourceSceneBinding.Source provider=(epoch,serial,begin,end)->{try{return Files.readAllBytes(dir.resolve("source-"+serial+".nsp"));}catch(Exception e){throw new RuntimeException(e);}};byte[] result=NativeSourceBackgroundBinding.bind(raw,binding,provider);if(result==null)throw new AssertionError("Missing source background");NativeBackgroundScene actual=new NativeBackgroundScene(result),expected=new NativeBackgroundScene(Files.readAllBytes(reference.resolve(file.getFileName())));NativeSceneSnapshot scene=actual.sky.scene;
 if(!Arrays.equals(bytes(scene.packedLayers()),bytes(legacy.sky.scene.packedLayers()))||!Arrays.equals(bytes(scene.provenance()),bytes(legacy.sky.scene.provenance())))throw new AssertionError("Original display layers changed");
 byte[] oldSky=section(raw,0),newSky=section(result,0);for(int i=0;i<scene.geometryCount();i++){NativeScenePacket p=scene.geometry(i);if(!Arrays.equals(bytes(p.data()),provider.packet(p.epoch,p.serial,p.beginRefresh,p.endRefresh)))throw new AssertionError("Wrong source geometry");if(!Arrays.equals(section(oldSky,i+1),section(newSky,i+1))||!Arrays.equals(section(raw,i+1),section(result,i+1)))throw new AssertionError("Captured sky/background changed");owners++;}
 if(!Arrays.equals(bytes(actual.exactRgba()),bytes(expected.exactRgba()))||!Arrays.equals(bytes(actual.sky.exactRgba()),bytes(expected.sky.exactRgba())))throw new AssertionError("Original source background/sky differs");rgba+=38400*2;
 if(NativeSourceBackgroundBinding.bind(raw,new NativeSourceSceneBinding(),(e,s,b,f)->null)!=null)throw new AssertionError("Missing source accepted");rejected++;try{NativeSourceBackgroundBinding.bind(raw,new NativeSourceSceneBinding(),(e,s,b,f)->{byte[] bad=provider.packet(e,s,b,f);ByteBuffer.wrap(bad).order(ByteOrder.LITTLE_ENDIAN).putInt(16,(int)s+1);return bad;});throw new AssertionError("Wrong source identity accepted");}catch(IllegalArgumentException expectedFailure){rejected++;}
 Files.write(dir.resolve("source-"+file.getFileName()),result);Arrays.fill(raw,(byte)0);if(!Arrays.equals(bytes(actual.exactRgba()),bytes(expected.exactRgba())))throw new AssertionError("Mutable original input");snapshots++;
 }}if(snapshots!=9||rejected!=18)throw new AssertionError("Incomplete scene set");System.out.println("PASS_SOURCE_BACKGROUND_BINDING snapshots="+snapshots+" owners="+owners+" background_and_sky_rgba_cells="+rgba+" missing_or_forged_rejected="+rejected);}
}
